package net.swordie.ms.loaders.enhance;

import net.swordie.ms.ServerConstants;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.random.RandomGenerator;

/** Shared reader for the TSV tables in data/resources/tms282/enhance (generated by _gen_enhance_tables.py from the
 * TMS 279 config and MetaMS 273 data). A missing file means "no data": every consumer then keeps its old hardcoded
 * behaviour. {@code -Dtms282.enhance.tables=false} disables all tables. */
public final class EnhanceTables {
    private EnhanceTables() { }

    public static boolean enabled() {
        return !"false".equalsIgnoreCase(System.getProperty("tms282.enhance.tables", "true"));
    }

    public static Path dir() {
        return Path.of(ServerConstants.RESOURCES_DIR, "tms282", "enhance");
    }

    /** Data rows (comments, blanks and the header line removed), or null if the table is absent/disabled. */
    static List<String[]> rows(String file) {
        if (!enabled()) return null;
        Path path = dir().resolve(file);
        if (!Files.isRegularFile(path)) return null;
        try {
            List<String[]> out = new ArrayList<>();
            boolean header = true;
            for (String line : Files.readAllLines(path, StandardCharsets.UTF_8)) {
                if (line.isBlank() || line.startsWith("#")) continue;
                if (header) { header = false; continue; }
                out.add(line.split("\t", -1));
            }
            return out;
        } catch (IOException e) {
            System.err.println("[enhance] cannot read " + path + ": " + e);
            return null;
        }
    }

    static void warn(String file, Object row, Exception e) {
        System.err.println("[enhance] " + file + ": skipped bad row " + row + " (" + e.getMessage() + ")");
    }

    /** Integer weights "k:w,k:w"; zero weights are dropped. {@link #pick} maps a uniform draw to a key. */
    public record Weighted(int[] keys, int[] cumulative, int total) {
        public static Weighted parse(String spec) {
            List<int[]> parts = new ArrayList<>();
            int total = 0;
            for (String part : spec.split(",")) {
                if (part.isBlank()) continue;
                String[] kv = part.split(":");
                if (kv.length != 2) throw new IllegalArgumentException("bad weight " + part);
                int key = Integer.parseInt(kv[0].trim()), w = Integer.parseInt(kv[1].trim());
                if (w < 0) throw new IllegalArgumentException("negative weight " + part);
                if (w == 0) continue;
                total = Math.addExact(total, w);
                parts.add(new int[]{key, total});
            }
            if (total <= 0) throw new IllegalArgumentException("empty weights " + spec);
            int[] k = new int[parts.size()], c = new int[parts.size()];
            for (int i = 0; i < k.length; i++) { k[i] = parts.get(i)[0]; c[i] = parts.get(i)[1]; }
            return new Weighted(k, c, total);
        }

        public int pick(RandomGenerator random) {
            int r = random.nextInt(total);
            for (int i = 0; i < cumulative.length; i++) if (r < cumulative[i]) return keys[i];
            throw new AssertionError();
        }

        public int weightOf(int key) {
            for (int i = 0; i < keys.length; i++) if (keys[i] == key) return cumulative[i] - (i == 0 ? 0 : cumulative[i - 1]);
            return 0;
        }

        public boolean contains(int key) {
            return weightOf(key) > 0;
        }
    }
}
